#!/usr/bin/env node
// Deterministic JS→Go conformance fixtures for the client order of encoded
// updates and state vectors.
//
// yjs writes the struct groups of an update and the entries of a state vector
// with clients descending (writeClientsStructs, writeStateVector,
// mergeUpdates). Each row replays a short session of four pinned peers, one
// with a multi-byte client ID, and records what every encoder yjs exposes
// writes for the peer that holds all four clients.
//
// Determinism: pinned clientIDs, canonical JSON, trailing newline.
// Regenerated by `make fixtures`; CI's drift gate diffs the result.
const Y = require('yjs')
const fs = require('fs')
const path = require('path')

const outDir = path.join(__dirname, '..', 'crdt', 'testdata')
const hex = (u8) => Buffer.from(u8).toString('hex')

const clients = [1, 2, 300, 4000000000]

// ops run in order; `snapshot` marks where the snapshot rows are taken.
const ops = [
	{ peer: 0, op: 'ins', pos: 0, s: 'hello' },
	{ op: 'sync', from: 0, to: 1 },
	{ peer: 1, op: 'ins', pos: 5, s: ' world' },
	{ peer: 2, op: 'mset', key: 'k', s: 'c' },
	{ peer: 3, op: 'ains', pos: 0, s: 'x' },
	{ op: 'sync', from: 1, to: 3 },
	{ op: 'sync', from: 2, to: 3 },
	{ peer: 3, op: 'del', pos: 1, n: 2 },
	{ peer: 0, op: 'mset', key: 'k', s: 'a' },
	{ op: 'sync', from: 0, to: 3 },
	{ op: 'snapshot' },
	{ peer: 3, op: 'ins', pos: 0, s: 'X' }
]

function row (name, gc) {
	const docs = clients.map((c) => {
		const d = new Y.Doc({ gc })
		d.clientID = c
		return d
	})
	const local = []
	docs.forEach((d) => d.on('update', (u, origin) => { if (origin !== 'sync') local.push(u) }))
	const full = docs[3]
	let snap = null
	for (const o of ops) {
		if (o.op === 'sync') {
			Y.applyUpdate(docs[o.to], Y.encodeStateAsUpdate(docs[o.from], Y.encodeStateVector(docs[o.to])), 'sync')
			continue
		}
		if (o.op === 'snapshot') {
			snap = Y.snapshot(full)
			continue
		}
		const d = docs[o.peer]
		switch (o.op) {
			case 'ins': d.getText('t').insert(o.pos, o.s); break
			case 'del': d.getText('t').delete(o.pos, o.n); break
			case 'mset': d.getMap('m').set(o.key, o.s); break
			case 'ains': d.getArray('a').insert(o.pos, [o.s]); break
		}
	}
	const v1 = Y.encodeStateAsUpdate(full)
	const v2 = Y.encodeStateAsUpdateV2(full)
	// The peer that has seen only clients 1 and 2.
	const sv = Y.encodeStateVector(docs[1])

	// A fresh peer receiving the whole state fires one update for all clients.
	const fresh = new Y.Doc({ gc })
	fresh.clientID = 5
	let received = null
	fresh.on('update', (u) => { received = u })
	Y.applyUpdate(fresh, v1)

	const out = {
		name,
		gc,
		clients,
		ops,
		sv: hex(sv),
		// Each peer's own updates, the input of the merge rows.
		local: local.map(hex),
		localV2: local.map((u) => hex(Y.convertUpdateFormatV1ToV2(u))),
		expected: {
			stateV1: hex(v1),
			stateV2: hex(v2),
			stateVector: hex(Y.encodeStateVector(full)),
			snapshot: hex(Y.encodeSnapshot(Y.snapshot(full))),
			diffStateV1: hex(Y.encodeStateAsUpdate(full, sv)),
			diffStateV2: hex(Y.encodeStateAsUpdateV2(full, sv)),
			received: hex(received),
			mergeV1: hex(Y.mergeUpdates(local)),
			mergeV2: hex(Y.mergeUpdatesV2(local.map((u) => Y.convertUpdateFormatV1ToV2(u)))),
			diffUpdateV1: hex(Y.diffUpdate(v1, sv)),
			diffUpdateV2: hex(Y.diffUpdateV2(v2, sv)),
			v1ToV2: hex(Y.convertUpdateFormatV1ToV2(v1)),
			v2ToV1: hex(Y.convertUpdateFormatV2ToV1(v2)),
			stateVectorFromV1: hex(Y.encodeStateVectorFromUpdate(v1)),
			stateVectorFromV2: hex(Y.encodeStateVectorFromUpdateV2(v2))
		}
	}
	if (!gc) {
		const restored = Y.createDocFromSnapshot(full, snap, new Y.Doc({ gc: false }))
		out.expected.fromSnapshot = hex(Y.encodeStateAsUpdate(restored))
	}
	return out
}

const rows = [row('four_peers_gc', true), row('four_peers_no_gc', false)]

const file = path.join(outDir, 'clientorder_yjs_fixtures.json')
fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n')
console.log(`wrote crdt/testdata/clientorder_yjs_fixtures.json (${rows.length} scenarios)`)
